//==================================================================================
// This is an autogenerated file. DO NOT EDIT.
//
// Description: Top module, connecting comparison and lookup logic
//==================================================================================

module {{ module }} #(
    // SKID_EN=1: instantiate the input AXI skid buffer (default — e.g. when this
    // is the top-level module). SKID_EN=0: bypass it (e.g. when parser_top owns
    // the skid). When bypassed the RTL is functionally identical to the original.
    parameter bit SKID_EN = 1
) (
    input  logic    clk,
    input  logic    rst,
    {% for port in custom_inputs -%}
    input  logic [{{ port.width - 1 }}:0] {{ port.name }},
    {% endfor -%}
    input  logic [{{ active_modules[0].din_bits - 1 }}:0]  data_in,
    input  logic    data_in_sop,
    input  logic    data_in_eop,
    input  logic    data_in_valid,
    input  logic    path_id_out_ready,

    output logic [{{ lookup_dout_outb_list[-1] - 1 }}:0]  path_id_out,
    output logic    path_id_out_valid,
    output logic    data_in_ready
);
    {#- Determine the Maximum ID to establish total pipeline latency #}
    {%- if active_modules %}
        {%- set max_id = active_modules[-1].id %}
    {%- else %}
        {%- set max_id = 0 %}
    {%- endif %}

    logic [{{ lookup_dout_outb_list[-1] - 1 }}:0] path_id_out_tmp;
    (* DONT_TOUCH = "TRUE" *) logic eop_d1, eop_d2;
    (* DONT_TOUCH = "TRUE" *) logic ready_r;
    {%- if max_id > 0 %}
    // flit_counter: 0 after SOP, increments each valid cycle, saturates at max_id
    (* DONT_TOUCH = "TRUE" *) logic [$clog2({{ max_id }}+1)-1:0] flit_counter;
    {%- endif %}
    {% for port in custom_inputs -%}
    (* DONT_TOUCH = "TRUE" *) logic [{{ port.width - 1 }}:0] {{ port.name }}_r;
    {% endfor -%}

    // ---- Input AXI skid buffer (SKID_EN=1) or direct passthrough (SKID_EN=0) ----
    // The core comparison/lookup pipeline always consumes the post-skid stream.
    logic [{{ active_modules[0].din_bits - 1 }}:0] core_data_in;
    logic core_data_in_sop, core_data_in_eop, core_data_in_valid;
    logic core_data_out_ready;

    // Existing ready logic, computed on the post-skid stream. Drives the skid's
    // downstream-ready input (SKID_EN=1) or data_in_ready directly (SKID_EN=0).
    assign core_data_out_ready = (core_data_in_valid && core_data_in_sop && path_id_out_ready) || ready_r;

    generate
    if (SKID_EN) begin : g_input_skid
        axi_skid #(.WIDTH({{ active_modules[0].din_bits }})) u_input_skid (
            .clk            (clk),
            .rst            (rst),
            .data_in        (data_in),
            .data_in_sop    (data_in_sop),
            .data_in_eop    (data_in_eop),
            .data_in_valid  (data_in_valid),
            .data_in_ready  (data_in_ready),
            .data_out       (core_data_in),
            .data_out_sop   (core_data_in_sop),
            .data_out_eop   (core_data_in_eop),
            .data_out_valid (core_data_in_valid),
            .data_out_ready (core_data_out_ready)
        );
    end else begin : g_no_skid
        assign core_data_in       = data_in;
        assign core_data_in_sop   = data_in_sop;
        assign core_data_in_eop   = data_in_eop;
        assign core_data_in_valid = data_in_valid;
        assign data_in_ready      = core_data_out_ready;
    end
    endgenerate

    {%- if max_id > 0 %}
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            flit_counter <= '0;
        end else if (core_data_in_valid) begin
            if (core_data_in_sop)
                flit_counter <= '0;
            else if (flit_counter < {{ max_id }})
                flit_counter <= flit_counter + 1'b1;
        end
    end
    {%- endif %}

    // EOP delayed two cycles: path_id_out captured on eop_d1 (latches stable),
    // path_id_out_valid asserted on eop_d2 exactly 2 cycles after EOP.
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            eop_d1 <= '0;
            eop_d2 <= '0;
        end else begin
            eop_d1 <= core_data_in_valid && core_data_in_eop;
            eop_d2 <= eop_d1;
        end
    end

    always_ff @(posedge clk) begin
        path_id_out <= path_id_out_tmp;
    end

    assign path_id_out_valid = eop_d2;

    // ready: sampled at SOP, held for the entire packet; re-evaluated at next SOP
    always_ff @(posedge clk or posedge rst) begin
        if (rst)
            ready_r <= '0;
        else if (core_data_in_valid && core_data_in_sop)
            ready_r <= path_id_out_ready;
    end
    // data_in_ready is driven by the skid handshake (SKID_EN=1) or by
    // core_data_out_ready in the g_no_skid generate branch (SKID_EN=0).

    {% if custom_inputs %}
    // Custom input pipeline registers
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
    {% for port in custom_inputs -%}
            {{ port.name }}_r <= '0;
    {% endfor %}
        end else if (core_data_in_valid) begin
    {% for port in custom_inputs -%}
            {{ port.name }}_r <= {{ port.name }};
    {% endfor %}
        end
    end
    {% endif %}

    // Comparison logic
    {%- if lookup_needed == 1 %}

        {%- for mod in active_modules %}
        // Module ID: {{ mod.id }}
        logic [{{ mod.dout_bits - 1 }}:0] dout_comparison_{{ mod.id }};
        (* DONT_TOUCH = "TRUE" *) logic [{{ mod.dout_bits - 1 }}:0] dout_comparison_{{ mod.id }}_latched;

        comparison_logic_{{ mod.id }}
        u_comp_{{ mod.id }} (
            .clk        (clk),
            {% for port in custom_inputs -%}
            .{{ port.name }} ({{ port.name }}_r),
            {% endfor -%}
            .data_in    (core_data_in),
            .data_out   (dout_comparison_{{ mod.id }})
        );

        {%- if mod.id == 0 %}
        // Module 0: flit 0 is on data_in at SOP — capture at SOP, no reset needed
        always_ff @(posedge clk) begin
            if (core_data_in_valid && core_data_in_sop)
                dout_comparison_{{ mod.id }}_latched <= dout_comparison_{{ mod.id }};
        end
        {%- else %}
        // SOP reset clears stale value; capture when flit {{ mod.id }} is on data_in
        always_ff @(posedge clk) begin
            if (core_data_in_valid && core_data_in_sop)
                dout_comparison_{{ mod.id }}_latched <= '0;
            else if (core_data_in_valid && (flit_counter == {{ mod.id - 1 }}))
                dout_comparison_{{ mod.id }}_latched <= dout_comparison_{{ mod.id }};
        end
        {%- endif %}

        {%- endfor %}

        // lookup_logic is purely combinational; no extra pipeline stage needed
        logic [{{ lookup_din_outb_list[-1] - 1 }}:0] lookup_input;

        assign lookup_input = {
            {%- for mod in active_modules -%}
                {%- if not loop.last %}
            dout_comparison_{{ mod.id }}_latched,
                {%- else %}
            dout_comparison_{{ mod.id }}_latched
                {%- endif -%}
            {%- endfor %}
        };

        lookup_logic
        u_lookup (
            .clk        (clk),
            .data_in    (lookup_input),
            .data_out   (path_id_out_tmp)
        );

    {%- else %}
        // Single comparison module — no lookup needed
        comparison_logic_{{ active_modules[0].id }}
        u_comp (
            .clk        (clk),
            {% for port in custom_inputs -%}
            .{{ port.name }} ({{ port.name }}_r),
            {% endfor -%}
            .data_in    (core_data_in),
            .data_out   (path_id_out_tmp)
        );
    {% endif %}

endmodule: {{ module }}
